const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([100.141422, 20.248364]);
  const buffer = point.buffer(500); // 500m buffer to capture river area

  // Date ranges for comparison
  const date2015 = ee.Date('2015-01-27');
  const date2020 = ee.Date('2020-01-25');
  const dateRange = 3; // +/- 3 days tolerance

  // 2. Data Acquisition - Landsat 8 Surface Reflectance
  function getL8Collection(targetDate, daysBuffer) {
    const startDate = targetDate.advance(-daysBuffer, 'day');
    const endDate = targetDate.advance(daysBuffer, 'day');

    return ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(buffer)
      .filterDate(startDate, endDate)
      .map(function(image) {
        // Apply cloud mask using QA_PIXEL band
        const qa = image.select('QA_PIXEL');
        const cloudMask = qa.bitwiseAnd(1 << 3).eq(0)  // Cloud
                          .and(qa.bitwiseAnd(1 << 4).eq(0)) // Cloud shadow
                          .and(qa.bitwiseAnd(1 << 1).eq(0)); // Dilated cloud

        // Scale reflectance bands and apply mask
        const opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
        return opticalBands.updateMask(cloudMask).copyProperties(image, ['system:time_start']);
      });
  }

  // Get collections for both years
  const col2015 = getL8Collection(date2015, dateRange);
  const col2020 = getL8Collection(date2020, dateRange);

  // Check collection sizes
  const size2015 = col2015.size().getInfo();
  const size2020 = col2020.size().getInfo();

  console.log(`2015 Images: ${size2015}, 2020 Images: ${size2020}`);

  if (size2015 === 0 || size2020 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get median composites to reduce noise
  const img2015 = col2015.median();
  const img2020 = col2020.median();

  // 3. Processing - Use red band (B4) as sediment proxy
  const band = 'SR_B4'; // Red band

  // Calculate mean reflectance in buffer
  const stats2015 = img2015.select(band).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 30,
    maxPixels: 1e9
  });

  const stats2020 = img2020.select(band).reduceRegion({
    reducer: ee.Reducer.count().combine(ee.Reducer.mean(), '', true),
    geometry: buffer,
    scale: 30,
    maxPixels: 1e9
  });

  const mean2015 = stats2015.get(band).getInfo();
  const stats2020Result = stats2020.getInfo();
  const mean2020 = stats2020Result[band + '_mean'];
  const count2020 = stats2020Result[band + '_count'];

  console.log(`2015 Mean Red Reflectance: ${mean2015 ? mean2015.toFixed(4) : 'No data'}`);
  console.log(`2020 Mean Red Reflectance: ${mean2020 ? mean2020.toFixed(4) : 'No data'}`);
  console.log(`2020 Valid Pixels: ${count2020}`);

  // 4. Validation & Final Answer
  if (mean2015 === null || mean2020 === null || 
      isNaN(mean2015) || isNaN(mean2020) || 
      count2020 === 0) {
    console.log("<answer>C2</answer>");
  } else if (mean2015 > mean2020) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
